import { spawnSync } from 'node:child_process';
import { resolve } from 'node:path';
import { defineConfig } from 'vitest/config';
import { buildPostgresOptions, normalizePostgresConnectionString } from '../src/connection-options.js';

/**
 * Vitest globalSetup for `@reading-advantage/auth` integration tests.
 *
 * Runs the Drizzle migration runner against the resolved test database
 * exactly once per test run. Drizzle migrations are idempotent.
 *
 * Test-DB resolution mirrors `apps/science-advantage/lib/test/resolve-test-database-url.ts`:
 *   1. `TEST_DATABASE_URL` — used verbatim.
 *   2. `DATABASE_URL` with `_test` appended to the pathname.
 *   3. Built-in default: `postgresql://postgres:postgres@localhost:5432/science_advantage_test`.
 *
 * The migration role (typically `postgres` locally) is the only one with
 * DELETE on `audit_events`, satisfying the append-only REVOKE — see
 * `measure/tracks/audit_log_retention_dsar_20260605/test-strategy.md` §1.
 */
function resolveTestDatabaseUrl(env: {
  DATABASE_URL?: string;
  TEST_DATABASE_URL?: string;
}): string {
  if (env.TEST_DATABASE_URL) return env.TEST_DATABASE_URL;
  const primary = env.DATABASE_URL ?? 'postgresql://postgres:postgres@localhost:5432/science_advantage';
  if (primary.endsWith('_test')) return primary;
  try {
    const url = new URL(primary);
    const pathname = url.pathname.replace(/\/$/, '');
    url.pathname = `${pathname}_test`;
    return url.toString();
  } catch {
    return `${primary}_test`;
  }
}

export default function globalSetup(): void {
  const databaseUrl = resolveTestDatabaseUrl(process.env);

  // Sanity check: confirm the URL parses before we hand it to pnpm.
  // This mirrors the same validation `createPrivilegedDb` performs at runtime.
  try {
    normalizePostgresConnectionString(databaseUrl);
    buildPostgresOptions(databaseUrl);
  } catch (error) {
    throw new Error(
      `[auth vitest.integration.global-setup] invalid test DB URL: ${databaseUrl} (${
        error instanceof Error ? error.message : 'unknown error'
      })`,
    );
  }

  // Run drizzle migrations via the same runner the science-advantage app uses.
  // We delegate to `pnpm --filter @reading-advantage/db migrate` so the
  // global drizzle-kit config + snapshots in `packages/db/drizzle.config.ts`
  // are honored.
  const result = spawnSync(
    'pnpm',
    ['--filter', '@reading-advantage/db', 'migrate'],
    {
      stdio: 'inherit',
      env: { ...process.env, DATABASE_URL: databaseUrl },
      cwd: resolve(__dirname, '../../../'),
    },
  );

  if (result.signal) {
    throw new Error(
      `[auth vitest.integration.global-setup] drizzle migrate killed by signal ${result.signal} (DATABASE_URL=${databaseUrl}).`,
    );
  }
  if (result.status !== 0) {
    throw new Error(
      `[auth vitest.integration.global-setup] drizzle migrate exited with status ${result.status} (DATABASE_URL=${databaseUrl}).`,
    );
  }

  // The purge function reads DIRECT_DATABASE_URL for the privileged connection
  // (DELETE on audit_events). The migration role and the privileged role are
  // the same in local dev (the `postgres` superuser). Setting both keeps the
  // app connection and the privileged connection pointed at the same DB.
  process.env.DIRECT_DATABASE_URL = databaseUrl;
}

/**
 * Per-file setup for `@reading-advantage/auth` integration tests.
 *
 * Sets `process.env.DATABASE_URL` to the `_test`-suffixed URL so that the
 * `@reading-advantage/db` client connects to the isolated test database.
 * Migration is handled once-per-run by `vitest.integration.global-setup.ts`.
 *
 * Does NOT touch the database here — keep this file fast and side-effect-light
 * so test files start up quickly.
 */

function resolveTestDatabaseUrl(env: {
  DATABASE_URL?: string;
  TEST_DATABASE_URL?: string;
}): string {
  if (env.TEST_DATABASE_URL) return env.TEST_DATABASE_URL;
  const primary = env.DATABASE_URL ?? 'postgresql://postgres:postgres@localhost:5432/science_advantage';
  if (primary.endsWith('_test')) return primary;
  try {
    const url = new URL(primary);
    const pathname = url.pathname.replace(/\/$/, '');
    url.pathname = `${pathname}_test`;
    return url.toString();
  } catch {
    return `${primary}_test`;
  }
}

process.env.DATABASE_URL = resolveTestDatabaseUrl(process.env);

import { defineConfig } from 'vitest/config';

/**
 * Vitest configuration for `@reading-advantage/auth` integration tests.
 *
 * Mirrors the pattern in `apps/science-advantage/vitest.integration.config.ts`:
 *   - `globalSetup` runs Drizzle migrations once against the resolved test DB
 *     (`vitest.integration.global-setup.ts`).
 *   - `setupFiles` points `DATABASE_URL` at the `_test` DB before each test
 *     file loads.
 *   - `singleFork: true` keeps the test DB connection state coherent across
 *     files (truncate/insert races are not a concern with the single-fork
 *     model).
 *
 * Usage:
 *   npx vitest run --config vitest.integration.config.ts
 */
export default defineConfig({
  test: {
    globals: true,
    environment: 'node',
    setupFiles: ['./vitest.integration.setup.ts'],
    globalSetup: ['./vitest.integration.global-setup.ts'],
    include: ['src/**/*.integration.test.ts'],
    pool: 'forks',
    poolOptions: {
      forks: {
        singleFork: true,
      },
    },
    testTimeout: 30_000,
  },
});

